create or replace function public.prevent_student_project_verification_change() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.is_tpo() and not (old.verification_status = 'Rework Required' and new.verification_status = 'Under Review' and new.status = 'Submitted') and (new.status <> old.status or new.feedback is distinct from old.feedback or new.verification_status <> old.verification_status or new.verified_by is distinct from old.verified_by or new.verified_at is distinct from old.verified_at) then raise exception 'Only TPO/admin can change project review fields'; end if; return new; end; $$;
